IL ) BETWEEN 218929896 AND 218929896 THEN ( DECODE(o997019.INDEBITOCREDITO,'D',o997019.VALANCAMENTO,'C',-o997019.VALANCAMENTO) ) ELSE 0 END) as C_5,SUM(CASE WHEN ( o997019.COCONTACONTABIL ) BETWEEN 631200000 AND 631200000 THEN ( DECODE(o997019.INDEBITOCREDITO,'D',o997019.VALANCAMENTO,'C',-o997019.VALANCAMENTO) ) ELSE 0 END) as C_6
